// Fixtures del test: mismo shape que 'Join send'. mock:'yes' lo frena el filtro.
return [{ json: {
  client: 'growbusy', week: '2999-W99', r2key: 'mock/integration-qex0qv3j.html',
  toEmail: 'gnomeaddict96@gmail.com', toName: 'QA', share: '0a3c91e963961d1ab0408fe0',
  html: '<html><body><h1>Mock</h1></body></html>',
  mock: 'yes'
} }];

// Arma el correo. Lee SOLO $input: producción llega vía 'Join send' y el
// test vía 'Mock fixtures' (mismo shape).
const d = $input.first().json;
const link = 'https://n8n.innerchildproject.us/webhook/gb.reporte.ver?share=' + d.share;
const subject = 'Reporte semanal GrowBusy — ' + d.week;
const hello = d.toName ? ('Hola ' + d.toName + ',') : 'Hola,';
const htmlbody = ['<!DOCTYPE html>', '<html lang="es">', '<head>', '<meta charset="UTF-8">',
'<meta name="viewport" content="width=device-width, initial-scale=1.0">',
'<title>' + subject + '</title>', '</head>',
'<body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Arial,Helvetica,sans-serif;">',
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;">',
'<tr><td align="center" style="padding:24px 12px;">',
'<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">',
'<tr><td style="background-color:#0a1a33;padding:20px 24px;text-align:center;color:#ffffff;font-size:20px;font-weight:bold;">GrowBusy</td></tr>',
'<tr><td style="padding:28px 28px 12px 28px;color:#1a1a1a;font-size:15px;line-height:1.6;">',
'<p>' + hello + '</p>',
'<p>Tu reporte de resultados de la semana <strong>' + d.week + '</strong> ya está listo.</p>',
'</td></tr>',
'<tr><td style="padding:0 28px 28px 28px;text-align:center;">',
'<a href="' + link + '" style="display:inline-block;background-color:#2196f3;color:#ffffff;text-decoration:none;font-size:16px;padding:12px 28px;border-radius:6px;">Ver reporte</a>',
'</td></tr>',
'<tr><td style="padding:0 28px 28px 28px;color:#666;font-size:12px;">',
'<p>Adjuntamos también el reporte en HTML. Este es un correo transaccional, no una campaña.</p>',
'</td></tr>',
'</table>', '</td></tr>', '</table>', '</body>', '</html>'].join('\n');
const b64 = Buffer.from(d.html || '', 'utf8').toString('base64');
return [{ json: { client: d.client || '', week: d.week || '', r2key: d.r2key || '',
  to: d.toEmail || '', subject: subject, htmlbody: htmlbody,
  attachContent: b64, attachName: 'reporte-' + (d.week || 'semana') + '.html',
  mock: d.mock || '' } }];
